public static void main(String[] args){
    int[] arr = {1, 2, 3, 4, 5, 6, 7};
    System.out.print(someMethod(arr));
}
public static int someMethod(int[] arr){
    return Arrays.stream(arr).filter(x -> x%2 != 0).map(x -> x*x).reduce(0, (a,b) -> a + b);
}

